import heapq

def sort_k_sorted(nums, k):
    heap = []                                 # a min-heap of the next k + 1 candidates
    out = []
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k:
            out.append(heapq.heappop(heap))   # the smallest of k + 1 neighbours is next in order
    while heap:
        out.append(heapq.heappop(heap))
    return out

int[] sortKSorted(int[] nums, int k) {
    PriorityQueue<Integer> heap = new PriorityQueue<>();   // the next k + 1 candidates
    int[] out = new int[nums.length];
    int filled = 0;
    for (int x : nums) {
        heap.offer(x);
        if (heap.size() > k) out[filled++] = heap.poll();  // the smallest of k + 1 neighbours is next
    }
    while (!heap.isEmpty()) out[filled++] = heap.poll();
    return out;
}

vector<int> sortKSorted(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> heap;   // the next k + 1 candidates
    vector<int> out;
    for (int x : nums) {
        heap.push(x);
        if ((int)heap.size() > k) {                        // the smallest of k + 1 neighbours is next
            out.push_back(heap.top());
            heap.pop();
        }
    }
    while (!heap.empty()) {
        out.push_back(heap.top());
        heap.pop();
    }
    return out;
}
